/**
 * Inline SVG glyphs for the OI workbench panel.
 *
 * The sidebar row glyph is the only DOM this plugin owns inside the
 * shell-owned row, so it carries `data-dsh-panel-entry="oi-workbench"` (the
 * semantic anchor skins resolve panel rows through). Every glyph strokes
 * `currentColor` and inherits the shell's text color, so light, dark and skinned
 * themes all render correctly.
 *
 * @module @muyangplus/dsh-oi-workbench/client/icons
 */
import type { ReactElement, ReactNode } from 'react'

/** The shell's icon share: square edge and selection state. */
export interface WorkbenchIconProps {
  readonly size: number
  readonly active: boolean
}

/** Props every small panel glyph accepts. */
export interface GlyphProps {
  readonly size?: number
}

/** Shared drawing attributes for the 16px glyph grid. */
const GLYPH = {
  viewBox: '0 0 16 16',
  fill: 'none',
  stroke: 'currentColor',
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
  'aria-hidden': true,
} as const

/** Shared drawing attributes for larger area glyphs (stat tiles). */
const TILE_GLYPH = { ...GLYPH, strokeWidth: 1.2 } as const

/**
 * The sidebar row glyph: a small terminal/box hybrid standing for the
 * problem-setting workbench.
 * @param props - the shell's icon share.
 * @returns the decorative workbench glyph.
 */
export function WorkbenchIcon({ size, active }: WorkbenchIconProps): ReactElement {
  return (
    <svg
      {...GLYPH}
      data-dsh-panel-entry="oi-workbench"
      width={size}
      height={size}
      strokeWidth={active ? 1.55 : 1.3}
    >
      <rect x="1.9" y="2.6" width="12.2" height="10.8" rx="2.2" />
      <path d="M4.7 6.2 6.6 8l-1.9 1.8" />
      <path d="M8.6 9.8h2.7" />
    </svg>
  )
}

/** Wrap one small glyph body in the shared 16px SVG frame. */
function Glyph({ size = 14, children }: GlyphProps & { readonly children: ReactNode }): ReactElement {
  return (
    <svg {...GLYPH} width={size} height={size} strokeWidth="1.4">
      {children}
    </svg>
  )
}

/** Refresh / reload snapshot. */
