/**
 * Typed browser-side client for the OI workbench host API.
 *
 * Every call resolves to an {@link ApiResult} — network failures, non-JSON
 * bodies, malformed envelopes and `ok: false` envelopes all become readable
 * Chinese error strings. Nothing in this module throws, because an uncaught
 * rejection inside a panel render would otherwise escape into the shell.
 *
 * Wire types are imported type-only from the frozen contract; the module is
 * erased at bundle time, so the client never depends on host code.
 *
 * @module @muyangplus/dsh-oi-workbench/client/api
 */
import type {
  ActionOutcome,
  ApiEnvelope,
  WorkbenchAction,
  WorkbenchState,
} from '../api/contract.ts'

/** Prefix of every host route; mirrors `API_PREFIX` in the frozen contract. */
const API_PREFIX = '/oi-workbench/api'

/** Readable success/failure result; never throws. */
export type ApiResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: string }

/** Timeout for one state snapshot read. */
const STATE_TIMEOUT_MS = 15_000

/** Timeout for one mutating action (the host may run a Python tool for it). */
const ACTION_TIMEOUT_MS = 180_000

/** Turn an unknown thrown value into one readable line. */
function describeError(error: unknown): string {
  if (error instanceof Error) {
    if (error.name === 'AbortError') return '请求超时或已取消'
    return error.message || error.name
  }
  return typeof error === 'string' ? error : '未知网络错误'
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

/**
 * Narrow one parsed response body to the wire envelope.
 * @param payload - parsed JSON value, or undefined when the body was empty.
 * @returns the narrowed envelope, or undefined when the body breaks the contract.
 */
function envelopeOf<T>(payload: unknown): ApiEnvelope<T> | undefined {
  if (!isRecord(payload) || typeof payload.ok !== 'boolean') return undefined
  if (payload.ok === false) {
    return typeof payload.error === 'string' ? { ok: false, error: payload.error } : undefined
  }
  if (!('value' in payload)) return undefined
  return { ok: true, value: payload.value as T }
}

/** One fetch round-trip that never throws and normalizes every failure mode. */
async function request<T>(
  path: string,
  init: RequestInit,
  timeoutMs: number,
): Promise<ApiResult<T>> {
  const controller = typeof AbortController === 'function' ? new AbortController() : undefined
  const timer = controller === undefined
    ? undefined
    : setTimeout(() => controller.abort(), timeoutMs)
  try {
    const response = await fetch(API_PREFIX + path, {
      cache: 'no-store',
      headers: { accept: 'application/json' },
      ...init,
      ...(controller === undefined ? {} : { signal: controller.signal }),
    })
    const text = await response.text()
    let payload: unknown
    try {
      payload = text.length > 0 ? JSON.parse(text) : undefined
    } catch {
      payload = undefined
    }
    const envelope = envelopeOf<T>(payload)
    if (envelope === undefined) {
      const snippet = text.trim().slice(0, 240)
      const reason = snippet.length > 0 ? `：${snippet}` : ''
      return { ok: false, error: `宿主返回了无法识别的响应（HTTP ${response.status}）${reason}` }
    }
    if (!envelope.ok) return { ok: false, error: envelope.error }
    if (!response.ok) {
      return { ok: false, error: `宿主返回 HTTP ${response.status} ${response.statusText}`.trim() }
    }
    return { ok: true, value: envelope.value }
  } catch (error) {
    return { ok: false, error: describeError(error) }
  } finally {
    if (timer !== undefined) clearTimeout(timer)
  }
}

/**
 * Read the current workbench snapshot.
 * @returns the state, or a readable error string.
 */
export function fetchState(): Promise<ApiResult<WorkbenchState>> {
  return request<WorkbenchState>('/state', { method: 'GET' }, STATE_TIMEOUT_MS)
}

/**
 * Ask the host to perform one action.
 * @param action - contract action payload.
 * @returns the outcome (which may itself carry `ok: false`), or a transport error.
 */
export function runAction(action: WorkbenchAction): Promise<ApiResult<ActionOutcome>> {
  return request<ActionOutcome>('/action', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(action),
  }, ACTION_TIMEOUT_MS)
}
