/** Bottom command log: message, argv, stdout, stderr, timing. */
function LogDrawer(props: { readonly log: LogEntry; readonly onDismiss: () => void }): ReactElement {
  const [expanded, setExpanded] = useState(true)
  const toneClass = props.log.tone === 'ok'
    ? 'oiwb-log-tone is-ok'
    : props.log.tone === 'error'
      ? 'oiwb-log-tone is-error'
      : 'oiwb-log-tone is-running'
  const toneText = props.log.tone === 'ok' ? '完成' : props.log.tone === 'error' ? '失败' : '进行中'
  const command = props.log.command
  const stdout = command?.stdout ?? ''
  const stderr = command?.stderr ?? ''
  return (
    <section className="oiwb-log" aria-live="polite">
      <header className="oiwb-log-head">
        <span className="oiwb-log-title"><TerminalIcon size={13} />{props.log.title}</span>
        <span className={toneClass}>{toneText}</span>
        {command === undefined ? null : (
          <span className="oiwb-log-meta">
            退出码 {command.exitCode} · {command.durationMs} ms
          </span>
        )}
        <span className="oiwb-log-actions">
          <button type="button" className="oiwb-btn ghost" onClick={() => setExpanded((value) => !value)}>
            {expanded ? '收起' : '展开'}
          </button>
          <button type="button" className="oiwb-btn icon" aria-label="关闭日志" onClick={props.onDismiss}>
            <CloseIcon size={12} />
          </button>
        </span>
      </header>
      {expanded ? (
        <div className="oiwb-log-body">
          {props.log.message === undefined || props.log.message === ''
            ? null
            : <p className="oiwb-log-msg">{props.log.message}</p>}
          {props.log.tone === 'running' ? (
            <div className="oiwb-running"><span className="oiwb-spinner" />执行中…</div>
          ) : null}
          {command === undefined ? null : (
            <>
              {command.argv.length === 0 ? null : (
                <div className="oiwb-log-argv"><code>{command.argv.join(' ')}</code></div>
              )}
              {stdout.trim() === '' ? null : (
                <>
                  <div className="oiwb-log-label">stdout</div>
                  <pre className="oiwb-pre">{stdout}</pre>
                </>
              )}
              {stderr.trim() === '' ? null : (
                <>
                  <div className="oiwb-log-label is-error">stderr</div>
                  <pre className="oiwb-pre is-error">{stderr}</pre>
                </>
              )}
              {stdout.trim() === '' && stderr.trim() === '' ? (
                <p className="oiwb-log-msg">（没有命令输出）</p>
              ) : null}
            </>
          )}
        </div>
      ) : null}
    </section>
  )
}

